L46_1 = "그리고 넌 저 사람 구속장치부터 풀어. 간부 정도 되면 푸는 법은 알고 있겠지?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あと、あの人の拘束から解除して。幹部なら解き方ぐらい知っているでしょ？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "And take that person's restraints off. I'm sure a person of your status knows how to, right?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "現在你先解開那個人的束縛裝置。你知道該怎麼解開吧？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "现在你先解开那个人的束缚装置。你知道该怎么解开吧？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "And take that person's restraints off. I'm sure a person of your status knows how to, right?"
L45_1.m_Talk_DEU = L46_1
