L47_1 = "알겠으니까… 좀 살살하지? 너 피 냄새 맡으면 머리가 이상해지지 않아?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "わかったから……ちょっと手加減てよ。　お前は血の臭いを嗅ぐと頭がおかしくなるんだから。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Fine... But easy with the saw, all right? Don't you go crazy when you smell blood?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "知道了……下手輕點？你聞到血腥味不會覺得頭暈嗎？"
L46_1.m_Talk_TWN = L47_1
