L4_1 = "지금 최고관리자와 그 부하들은 우물에 모여있을 거야. 당신이 필요한 것도 거기서 찾을 수 있을 거고."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "今最高管理者とその部下たちは井戸に集まっているわ。お前に必要なものもそこにある。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The Supreme Administrator and his subordinates should be gathered at the Well right now. And you'll be able to find what you need there."
L3_1.m_Talk_ENG = L4_1
L4_1 = "現在最高管理者和他的手下們應該都在井邊。你需要的東西也在那裡。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "听好了，现在最高管理者和他的手下们应该都在井边。你需要的东西也在那里。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "The Supreme Administrator and his subordinates should be gathered at the Well right now. And you'll be able to find what you need there."
L3_1.m_Talk_DEU = L4_1
L4_1 = "The Supreme Administrator and his subordinates should be gathered at the Well right now. And you'll be able to find what you need there."
L3_1.m_Talk_FRA = L4_1
