L4_1.m_bCharPinup = true
L5_1 = "당신이 도착할 때쯤이면 펠릭스도 물러난 뒤일 테니. 굳이 싸울 필요도 없어. 잔챙이들 겁만 주면 돼."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "お前が着く頃にはフェリックスも引き下がっているでしょうし、戦う必要はないわ。雑魚どもをちょっと脅すだけで十分よ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "By the time you arrive, Felix will have retreated. There's no need to fight. Just give the grunts a little scare."
L4_1.m_Talk_ENG = L5_1
L5_1 = "等你到那裡時，緋莉克絲也該撤退了。沒必要硬碰硬，嚇唬嚇唬那些小嘍囉就行了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "等你到那里时，菲利克斯也该撤退了。没必要硬拼，吓唬吓唬那些小喽啰就行。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "By the time you arrive, Felix will have retreated. There's no need to fight. Just give the grunts a little scare."
L4_1.m_Talk_DEU = L5_1
