L6_1 = "생면부지인 놈들이 서로 죽자고 싸우더니 이젠 다 같이 날 구하려 드는군."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "初対面同士で殺し合うのかと思ったら、今度はみんなして私を助けようとするのか。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "At first, you two were fighting each other to the death. But now, you're working together to save me."
L5_1.m_Talk_ENG = L6_1
L6_1 = "你們二個原本還水火不容的，現在卻一起來救我？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "你们两个家伙之前还为了素不相识的我打生打死，现在却携起手来救我了？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "At first, you two were fighting each other to the death. But now, you're working together to save me."
L5_1.m_Talk_DEU = L6_1
L6_1 = "At first, you two were fighting each other to the death. But now, you're working together to save me."
L5_1.m_Talk_FRA = L6_1
