L12_1 = "USER_ADMIN_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "듣자니 자네의 실험 구역에 무슨 문제가 생긴 것 같던데."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "聞いたところ、君の実験区域に何か問題が発生したようだが。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "It sounds like something went wrong in your testing area."
L11_1.m_Talk_ENG = L12_1
L12_1 = "聽說你的實驗區出問題了吧。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "听说你的实验区出问题了吧。"
