L13_1 = "맞아. 당신의 직원을 가둬 놓고 기회를 봐서 제거하려 했는데, 차질이 생겼어."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そうだ。君の社員を監禁して、隙を見て始末しようとしたのだが……問題が生じた。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "You're right. I was waiting for the perfect time to dispose of an employee of yours I had captured, but there seems to be a setback."
L12_1.m_Talk_ENG = L13_1
L13_1 = "沒錯。本來這應該是除掉你那個員工的完美時機。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "没错。本来这应该是除掉你那个职员的完美时机。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "You're right. I was waiting for the perfect time to dispose of an employee of yours I had captured, but there seems to be a setback."
