L14_1 = "아마도 날 싫어하는 누가 수를 쓴 거겠지. 흔한 일이야."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "おそらく私のことが気に入らない誰かが手を回したんだろう。よくあることだ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "My guess is that someone who dislikes me is trying to sabotage me. It happens all the time."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我猜測有討厭我的人在背後耍了什麼手段。不過這也是常有的事。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "我猜测有讨厌我的人在背后耍了什么手段。不过这也是常有的事。"
