L23_1.m_Talk_JPN = L24_1
L24_1 = "It's because you didn't panic when you saw the light coming out of the Well."
L23_1.m_Talk_ENG = L24_1
L24_1 = "因為剛才你看到井中噴湧出的光芒，並沒有露出慌張的表情。"
