L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L27_1.m_bCharPinup = true
L28_1 = "발키리가 죽지 않고 힘까지 온전히 되찾아버리면, 다음 클리포트 게임에서 인류는 발키리 한 명의 힘에만 의존하게 될 테니까."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ヴァルキリーが死なず、完全に力を取り戻したら、次のクリフォトゲームで人類はヴァルキリー1人の力に頼ることになる。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "If Valkyrie doesn't die and regains all her power, then humanity will rely solely on her in the next Qliphoth Game."
L27_1.m_Talk_ENG = L28_1
L28_1 = "如果女武神沒有死，並且完全恢復了力量的話，那麼在下一場逆卡巴拉遊戲中，人類將只會依靠一名女武神的力量。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "如果女武神没有死，并且完全恢复了力量的话，那么在下一场神圣战役中，人类将只会依靠一名女武神的力量。"
L27_1.m_Talk_SCN = L28_1
