L39_1 = "저들에겐 우릴 막아설 명분이 있어. 침입자 신분인 우리가 저들을 죽여선 곤란하네."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "彼らには私たちを阻止する口実がある。侵入者である私たちが彼らを殺してはならない。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "They have a reason to stop us. As trespassers of their land, killing them will cause us more trouble."
L38_1.m_Talk_ENG = L39_1
L39_1 = "他們有正當的理由阻止我們。作為入侵者的我們，殺了他們會很麻煩。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "他们有正当的理由阻止我们。作为入侵者的我们，杀了他们会很麻烦。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "They have a reason to stop us. As trespassers of their land, killing them will cause us more trouble."
L38_1.m_Talk_DEU = L39_1
L39_1 = "They have a reason to stop us. As trespassers of their land, killing them will cause us more trouble."
L38_1.m_Talk_FRA = L39_1
