L40_1 = "USER_ADMIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "그랬다간 관리국에 반발하는 북방합의체의 강경함에 힘을 실어주는 꼴이 될 테니 말이야."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "殺せば、管理局に反発している北方合意体に都合のいい口実を与えてしまう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Furthermore, doing so will strengthen the Northern Union's hardline stance against the Administration."
L39_1.m_Talk_ENG = L40_1
L40_1 = "那樣的話，就會助長北方和議會對抗管理局的強硬態度。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "那样的话，就会助长北方联盟对抗管理局的强硬态度。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Furthermore, doing so will strengthen the Northern Union's hardline stance against the Administration."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Furthermore, doing so will strengthen the Northern Union's hardline stance against the Administration."
L39_1.m_Talk_FRA = L40_1
