L44_1 = "당신은 궁지에 몰린 채로도 뒷일을 생각하는구나."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "君は窮地に追い込まれても先のことを考えるのか。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "You seem to be thinking steps ahead even when you're cornered."
