L47_1.m_bCharPinupEasingTime = 0.3
L48_1 = "예? 기껏 포로들은 잡았는데 그냥 가신다고요?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "え？　せっかく捕虜を捕まえたのに、このまま帰るのですか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "What? We have captured them as prisoners, but you're leaving?"
