L49_1 = "그렇다고 합의체 영토 안에서 날뛰는 그림자를 방치해둘 순 없지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "合意体の領土内で暴れるシャドウを放置するわけにもいかないだろう。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "There is a Shadow on the loose in our territory and it needs to be dealt with."
L48_1.m_Talk_ENG = L49_1
L49_1 = "不能放任在我們北方和議會領土上肆虐的暗影不管。"
