L50_1 = "난 그림자 토벌을 지원할 테니, 포로는 당신이 알아서 처리해."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "私はシャドウ討伐を支援する。捕虜は君の好きなようにするといい。"
